<script setup>
import {computed, ref} from 'vue'
import {calendarDays, localDateKey, moveCalendar, parseCalendarDate, plansOnDate} from '@/features/planner/lib/calendar'
import {estimateMinutes, bucketTitle} from '@/features/planner/dailyPlanner'
const props = defineProps({plans: {type:Array,default:()=>[]}, modelValue:String, loading:Boolean, offline:Boolean})
const emit = defineEmits(['update:modelValue','create','edit','players','duplicate','refresh'])
const mode = ref('week'), status = ref('all')
const days = computed(() => calendarDays(props.modelValue,mode.value))
const selectedPlans = computed(() => plansOnDate(props.plans,props.modelValue,status.value))
const forDay = day => plansOnDate(props.plans,day,status.value)
const label = (date, options) => parseCalendarDate(date).toLocaleDateString(undefined,options)
const heading = computed(() => mode.value==='month' ? label(props.modelValue,{month:'long',year:'numeric'}) : `${label(days.value[0],{month:'short',day:'numeric'})} – ${label(days.value[6],{month:'short',day:'numeric',year:'numeric'})}`)
function move(direction) {emit('update:modelValue',moveCalendar(props.modelValue,mode.value,direction))}
</script>
<template>
  <section class="planner-calendar" aria-label="Workout calendar">
    <header class="calendar-toolbar"><div class="calendar-navigation"><button aria-label="Previous period" @click="move(-1)">‹</button><button @click="emit('update:modelValue',localDateKey())">Today</button><button aria-label="Next period" @click="move(1)">›</button><h2 aria-live="polite">{{ heading }}</h2></div><div class="calendar-options"><label class="calendar-jump">Go to date<input type="date" :value="modelValue" @change="$event.target.value && emit('update:modelValue',$event.target.value)"></label><select v-model="status" aria-label="Filter plan status"><option value="all">All plans</option><option value="draft">Drafts</option><option value="published">Published</option></select><div class="view-switch"><button v-for="view in ['week','month']" :key="view" :aria-pressed="mode===view" :class="{active:mode===view}" @click="mode=view">{{ view }}</button></div></div></header>
    <div class="calendar-legend"><span><i class="draft-dot"></i>Draft · not visible to players</span><span><i class="published-dot"></i>Published · available to assigned players</span><button :disabled="loading" @click="emit('refresh')">{{ loading?'Refreshing…':'Refresh' }}</button></div>
    <p v-if="offline" class="calendar-warning" role="alert">Couldn’t refresh plans. Displayed plans may be out of date.</p>
    <p v-if="loading" role="status" class="calendar-loading">Loading scheduled workouts…</p>
    <div class="calendar-scroll"><div class="calendar-grid" :class="mode"><div v-for="day in ['Mon','Tue','Wed','Thu','Fri','Sat','Sun']" :key="day" class="weekday">{{ day }}</div><div v-for="day in days" :key="day" class="calendar-day" :class="{selected:day===modelValue,today:day===localDateKey(),muted:mode==='month'&&day.slice(0,7)!==modelValue.slice(0,7)}"><button class="day-label" :aria-label="label(day,{weekday:'long',month:'long',day:'numeric',year:'numeric'})" :aria-pressed="day===modelValue" @click="emit('update:modelValue',day)"><span>{{ parseCalendarDate(day).getDate() }}</span><small v-if="day===localDateKey()">Today</small></button><button v-for="plan in forDay(day)" :key="plan.id" class="calendar-event" :class="plan.status==='published'?'published':'draft'" @click="emit('update:modelValue',day)"><strong>{{ plan.name || 'Untitled workout' }}</strong><small>{{ plan.status==='published'?'Published':'Draft' }} · {{ estimateMinutes(plan) }} min</small><small>{{ plan.assignedPlayerIds?.length || 0 }} players</small></button><button class="add-day" :aria-label="`Add workout on ${day}`" @click="emit('create',day)">+ Add workout</button></div></div></div>
    <section class="selected-day" aria-live="polite"><header><div><small>SELECTED DAY</small><h2>{{ label(modelValue,{weekday:'long',month:'long',day:'numeric'}) }}</h2></div><button class="calendar-primary" @click="emit('create',modelValue)">+ Plan this day</button></header><div v-if="!selectedPlans.length" class="day-empty">{{ loading ? 'Loading…' : offline ? 'Plans are unavailable. Refresh to try again.' : status==='all' ? 'No workouts scheduled. Add a workout, or leave this day open.' : 'No plans match this status filter.' }}</div><article v-for="plan in selectedPlans" :key="plan.id" class="day-plan"><div><span class="status-badge" :class="plan.status">{{ plan.status==='published'?'Published':'Draft' }}</span><h3>{{ plan.name || 'Untitled workout' }}</h3><p>{{ estimateMinutes(plan) }} min · {{ plan.assignedPlayerIds?.length || 0 }} players · {{ plan.workloadLevel || 'Workload not set' }}</p><p v-if="plan.primaryGoal">{{ plan.primaryGoal }}</p><div class="workout-blocks"><span v-for="bucket in plan.buckets" :key="bucket.type">{{ bucketTitle(bucket.type) }}</span></div><small>{{ plan.status==='published'?'Players can open this workout.':'Review exercises and assignments, then publish to make this available to players.' }}</small></div><div class="day-actions"><button class="calendar-primary" @click="emit('edit',plan)">{{ plan.status==='published'?'Edit workout':'Review & publish' }}</button><button v-if="plan.status==='published'" @click="emit('players',plan)">Player progress</button><button @click="emit('duplicate',plan)">Duplicate</button></div></article></section>
  </section>
</template>
<style scoped>
.planner-calendar{background:#101b2d;border:1px solid #30415a;border-radius:14px;overflow:hidden;margin-bottom:22px;color:#eef3fb}.calendar-toolbar{padding:20px;display:flex;flex-wrap:wrap;justify-content:space-between;gap:16px}.calendar-navigation,.calendar-options{display:flex;align-items:center;gap:8px;flex-wrap:wrap}h2{font-size:19px;font-weight:750}.calendar-navigation h2{margin-left:8px}button,select,input{color:#d1dded;background:#1b2a40;border:1px solid #3a4d67;border-radius:6px;padding:9px 12px;font-size:12px;min-height:36px}button:hover{border-color:#9bb3d5;background:#263954}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #83b9ff;outline-offset:2px}.calendar-jump{font-size:10px;color:#a7b9d1;display:flex;align-items:center;gap:7px}input{color-scheme:dark}.view-switch{display:flex}.view-switch button{text-transform:capitalize}.view-switch .active,.calendar-primary{background:#c91e32;color:white;border-color:#ec4355}.calendar-legend{display:flex;align-items:center;flex-wrap:wrap;gap:18px;padding:0 20px 16px;color:#a9bad2;font-size:11px}.calendar-legend>span{display:flex;gap:6px;align-items:center}.calendar-legend i{width:7px;height:7px;border-radius:50%}.draft-dot{background:#f6b652}.published-dot{background:#48cead}.calendar-legend button{margin-left:auto}.calendar-scroll{overflow-x:auto}.calendar-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));min-width:750px}.weekday{padding:10px 12px;border-top:1px solid #2c3c52;border-bottom:1px solid #2c3c52;color:#95abc9;text-transform:uppercase;font-size:10px;letter-spacing:1px}.calendar-day{min-height:190px;padding:8px;border-right:1px solid #2c3c52;border-bottom:1px solid #2c3c52;background:#0c1728;min-width:0}.month .calendar-day{min-height:130px}.calendar-day.selected{background:#182b45;box-shadow:inset 0 0 0 2px #659fe0}.calendar-day.muted{background:#0a1220}.muted .day-label{color:#788ca7}.day-label{display:flex;align-items:center;gap:6px;padding:3px 5px;border:0;background:none;width:100%;text-align:left}.day-label span{width:28px;height:28px;display:grid;place-items:center;font-size:14px}.today .day-label span{background:#d7293c;border-radius:50%;color:white}.day-label small{font-size:9px}.calendar-event{display:block;text-align:left;width:100%;margin:6px 0;padding:8px;background:#3c2b1e;border:1px solid #815c2c;border-left:3px solid #f6b652;overflow-wrap:anywhere}.calendar-event strong{display:block;font-size:11px;line-height:1.4;color:#f2eee7}.calendar-event small{display:block;font-size:9px;margin-top:4px;color:#c6b9a5}.calendar-event.published{background:#14342f;border-color:#2a6558;border-left-color:#48cead}.calendar-event.published small{color:#a0d6c9}.add-day{border:0;background:none;font-size:10px;color:#a1b4cf;padding:6px 3px}.selected-day{padding:22px}.selected-day>header{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:16px}.selected-day small{font-size:11px;color:#9aafcb}.day-empty{padding:25px;border:1px dashed #3a4d66;border-radius:9px;color:#aabdd6;font-size:13px}.day-plan{display:flex;justify-content:space-between;gap:20px;padding:18px;background:#0b1627;border:1px solid #2a3c55;border-radius:10px;margin-top:12px}.day-plan h3{font-size:18px;font-weight:750;margin:8px 0}.day-plan p{font-size:12px;color:#a8bad2;margin:7px 0}.status-badge{font-size:10px;color:#f6b652;text-transform:uppercase}.status-badge.published{color:#48cead}.day-actions{display:flex;flex-direction:column;gap:8px;min-width:145px}.workout-blocks{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0}.workout-blocks span{font-size:11px;padding:5px 8px;border:1px solid #31435b;border-radius:5px;color:#c0d1e8}.calendar-warning,.calendar-loading{padding:12px 20px;color:#edc181;font-size:13px}@media(max-width:650px){.calendar-toolbar,.selected-day{padding:14px}.calendar-options{width:100%}.calendar-navigation h2{font-size:15px}.day-plan{flex-direction:column}.day-actions{flex-direction:row;flex-wrap:wrap}.calendar-legend{padding:0 14px 14px;gap:10px}.selected-day h2{font-size:16px}.selected-day>header{flex-wrap:wrap}}
</style>
